-- Generated by npm run menus:seed from supabase/menus/*.json. Do not edit by hand.
-- Real menus taken from each brand's public site. Photos stay on the brand's servers.
-- A null price means the brand does not publish one.

with r as (
  insert into public.restaurants (name, cuisine, logo, logo_bg, delivery_link)
  values ('BBQ', 'Chicken', 'https://bbq.co.kr/images/symbols/logo-red.svg', '#ffffff', 'https://bbq.co.kr')
  returning id
)
insert into public.menu_items (restaurant_id, name, category, description, photo, price, sort_order)
select r.id, v.* from r, (values
  ('BBQ 황올 미니 콤보 세트', '세트', '겉은 바삭 육즙 가득한 부드러운 속살이 환상적인 건강한 치킨 비비큐의 시그니처 메뉴 후라이드의 대명사 황금올리브치킨™닭다리2개,윙&봉 각 2개씩+ 콜라500ml + 치킨무 [땅콩 알러지 주의]/기본 소스는 미포함이며, 옵션 추가 가능합니다.', 'https://static.bbqorder.co.kr/menu/732c7367d68b48930787fb354_81eb1166-c285-43f3-a356-c2a90f30efed.jpg', 14000::integer, 0::integer),
